{"name": "exec", "call_id": "call_ea12babbfa2e4927abf4f74337eaee83", "input": "text(await tools.apply_patch("*** Begin Patch\n*** Add File: [PROJECT_WORKSPACE]/output/live-buffer-board-20261019/verify_host.py\n+from concurrent.futures import ThreadPoolExecutor\n+from pathlib import Path\n+import json,os,subprocess\n+out=Path(__file__).resolve().parent\n+win=out.parents[1];src=win/'project/app/bilibili_live'\n+candidate=out/'source/apps/system/bilibili_live'\n+prior=win/'output/live-buffer-20261019'\n+fast=win/'output/live-buffer-3s-fast-20261019'\n+build=out/'host';build.mkdir(exist_ok=True)\n+flags=['-g','-O1','-fsanitize=address,undefined','-fno-omit-frame-pointer','-pthread','-DUSE_DEFAULT_STDLIB',\n+       '-I'+str(candidate),'-I'+str(src),'-I'+str(src/'local_vendor/helix')]\n+probe=(fast/'fast_probe.c').read_text()\n+probe=probe.replace('s.av=bili_av_create(&ops,&s,&s.cancel);',\n+    'assert(!bili_av_test_mode(atoi(getenv(\"LIVE_MODE\"))));s.av=bili_av_create(&ops,&s,&s.cancel);')\n+(build/'probe.c').write_text(probe)\n+objects=[p for p in Path('/home/flash/vela-p4/out/live-before').glob('*.o')\n+    if not p.name.startswith(('bili_av-','test_live_av-','decoder-delay-','bili_flv-','bili_sps-'))]\n+objects += [prior/'build/decoder-delay.o',prior/'build/bili_flv.o',prior/'build/bili_sps.o']\n+for name,p in [('probe',build/'probe.c'),('av',candidate/'bili_av.c')]:\n+    obj=build/(name+'.o');subprocess.run(['cc',*flags,'-c',p,'-o',obj],check=True);objects.append(obj)\n+binary=build/'probe'\n+subprocess.run(['g++','-pthread','-fsanitize=address,undefined',*objects,'-lm','-o',binary],check=True)\n+fixture=prior/'build/fixture.flv'\n+reference={int(l.split(',')[1]):l.split(',')[3] for l in (fast/'normal-buffered.csv').read_text().splitlines()[1:]}\n+def test(mode):\n+    trace=build/f'mode{mode}.csv'\n+    with (build/f'mode{mode}.log').open('w') as log:\n+        subprocess.run([binary,fixture,'3000','10000','1',trace],env={**os.environ,'LIVE_MODE':str(mode)},\n+            stdout=log,stderr=subprocess.STDOUT,check=True,timeout=30)\n+    text=(build/f'mode{mode}.log').read_text()\n+    rows=[l.split(',') for l in trace.read_text().splitlines()[1:]]\n+    assert len(rows)>100\n+    assert all(reference[int(l[1])]==l[3] for l in rows)\n+    assert 'ERROR: AddressSanitizer' not in text and 'LeakSanitizer:' not in text\n+    r=json.loads(next(l for l in text.splitlines() if l.startswith('{')))\n+    print('PASS_BOARD_SOURCE_HOST',mode,r['frames'],'I420 hashes match',flush=True)\n+    return dict(mode=mode,frames=r['frames'],hash_match=True)\n+with ThreadPoolExecutor(max_workers=3) as pool:results=list(pool.map(test,[0,1,2]))\n+with (build/'cancel.log').open('w') as log:\n+    subprocess.run([binary,fixture,'3000','10000','1',build/'unused.csv'],\n+        env={**os.environ,'LIVE_MODE':'2','CANCEL_PREROLL':'1'},stdout=log,stderr=subprocess.STDOUT,check=True,timeout=5)\n+cancel=json.loads(next(l for l in (build/'cancel.log').read_text().splitlines() if l.startswith('{')))\n+assert cancel['stop_join_ms']<500\n+(out/'host-validation.json').write_text(json.dumps(dict(modes=results,cancel=cancel),indent=2)+'\\n')\n+print('BOARD_SOURCE_HOST_CHECKS_COMPLETE',flush=True)\n*** End Patch"));
