{"name": "exec", "call_id": "call_bb302abf6fb247ebafd68b3616a08d24", "input": "text(await tools.apply_patch("*** Begin Patch\n*** Add File: [PROJECT_WORKSPACE]/output/live-buffer-board-20261019/deploy.py\n+\"\"\"Flash only the checked app range; retain exact prior image for rollback.\"\"\"\n+from pathlib import Path\n+import hashlib,json,re,subprocess,sys,time\n+from serial.tools import list_ports\n+out=Path(__file__).resolve().parent;win=out.parents[1]\n+sys.path.insert(0,str(win/'project/tools'))\n+from grok_board_io import Console\n+fw=out/'firmware/nuttx.bin'\n+old=win/'output/cli-refactor-20261019/firmware/nuttx.bin'\n+meta=json.loads(fw.with_name('verification.json').read_text())\n+sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()\n+assert sha(fw)==meta['sha256']['nuttx.bin'] and sha(old)==meta['baseline_sha256']\n+assert ((fw.stat().st_size+0x2000+4095)&~4095)<0xc00000\n+assert (out/'host-validation.json').exists()\n+report=dict(board_written=False,boot_verified=False,rollback=False,data_written=False,\n+            candidate_sha256=sha(fw),rollback_sha256=sha(old))\n+def save():(out/'deployment.json').write_text(json.dumps(report,indent=2)+'\\n')\n+def wait_port():\n+    until=time.monotonic()+35\n+    while time.monotonic()<until:\n+        ports=[p for p in list_ports.comports() if p.device=='COM4' and\n+               (p.vid,p.pid)==(0x303a,0x1001) and (p.serial_number or '').lower()=='[REDACTED:mac]']\n+        if len(ports)==1:return\n+        time.sleep(.3)\n+    raise RuntimeError('Expected board did not reconnect')\n+def flash(args,label):\n+    wait_port()\n+    with (out/(label+'.log')).open('w',encoding='utf-8') as log:\n+        subprocess.run([sys.executable,'-m','esptool','--chip','esp32p4','--port','COM4','--baud','460800',\n+            '--before','usb-reset','--after','watchdog-reset',*args],stdout=log,stderr=subprocess.STDOUT,check=True,timeout=180)\n+save()\n+with (out/'before-flash.log').open('w',encoding='utf-8') as log:\n+    c=Console(log=log)\n+    try:\n+        status=c.command('desktop ui chat-status')\n+        assert 'phase=1 ' in status,'Existing conversation is active'\n+        c.command('desktop ui bilibili-stop')\n+        report['heap_before']=c.command('free')\n+    finally:c.close()\n+flash(['verify-flash','0x2000',str(old)],'verify-running-image')\n+report['running_image_verified']=True;save()\n+print('RUNNING_IMAGE_VERIFIED',flush=True)\n+try:\n+    report['write_started']=True;save()\n+    flash(['write-flash','0x2000',str(fw)],'flash')\n+    report['board_written']=True;save();print('LIVE_TEST_IMAGE_FLASHED',flush=True)\n+    wait_port();time.sleep(2)\n+    with (out/'boot.log').open('w',encoding='utf-8') as log:\n+        c=Console(log=log)\n+        try:\n+            until=time.monotonic()+5\n+            while time.monotonic()<until:\n+                text=c.serial.read(c.serial.in_waiting or 1).decode(errors='replace');log.write(text)\n+                assert not re.search('PANIC|Guru Meditation|Assertion failed|Load access fault|Store access fault',text,re.I)\n+            assert 'esp32p4-function-ev-board' in c.command('uname -a')\n+            mount=c.command('mount');assert '/data type smartfs' in mount and '/sdcard type vfat' in mount\n+            assert 'loaded=1 configured=1 phase=1' in c.command('desktop ui chat-status')\n+            assert 'next_mode=2 buffer_ms=3000 late_target=20' in c.command('desktop live-test 2')\n+            report['heap_after_boot']=c.command('free')\n+            report['boot_verified']=True;save()\n+        finally:c.close()\n+except Exception as error:\n+    report['error']=repr(error);save()\n+    if report.get('write_started') and not report['boot_verified']:\n+        flash(['write-flash','0x2000',str(old)],'rollback')\n+        report['rollback']=True;save()\n+    raise\n+meta.update(board_written=True,boot_verified=True)\n+fw.with_name('verification.json').write_text(json.dumps(meta,indent=2)+'\\n')\n+print('LIVE_TEST_BOOT_VERIFIED',flush=True)\n*** End Patch"));
