{"name": "exec", "call_id": "call_7f21616fb67948f998d8326284a11562", "input": "text(await tools.apply_patch("*** Begin Patch\n*** Add File: [PROJECT_WORKSPACE]/output/live-buffer-board-20261019/board_ab.py\n+\"\"\"Same-firmware live A/B; records physical USB serial without host decoding.\"\"\"\n+from pathlib import Path\n+from datetime import datetime\n+import json,re,sys,time\n+out=Path(__file__).resolve().parent;win=out.parents[1]\n+sys.path.insert(0,str(win/'project/tools'))\n+from grok_board_io import Console\n+assert json.loads((out/'deployment.json').read_text())['boot_verified']\n+events=[]\n+def event(kind,**kw):\n+    row=dict(at=datetime.now().astimezone().isoformat(timespec='milliseconds'),kind=kind,**kw)\n+    events.append(row);(out/'timeline.json').write_text(json.dumps(events,indent=2)+'\\n')\n+    print(json.dumps(row),flush=True)\n+fault=re.compile(r'PANIC|Guru Meditation|Assertion failed|Load access fault|Store access fault',re.I)\n+\n+def run_mode(mode):\n+    label=f'mode{mode}'\n+    with (out/(label+'.log')).open('w',encoding='utf-8') as log:\n+        c=Console(log=log)\n+        try:\n+            c.command('desktop ui bilibili-stop');time.sleep(1)\n+            c.command('desktop ui home');c.command('desktop ppa-mode 1')\n+            assert f'next_mode={mode}' in c.command(f'desktop live-test {mode}')\n+            c.command('desktop media-fps 10')\n+            before=c.command('free');event('start',mode=mode)\n+            c.command('desktop ui bilibili-play:6')\n+            start=time.monotonic();first=None;pending='';last_report=start;latest='';free_done=False\n+            while time.monotonic()-start<125:\n+                data=c.serial.read(c.serial.in_waiting or 1).decode(errors='replace')\n+                if data:\n+                    log.write(data);log.flush();pending+=data\n+                    assert not fault.search(data),data\n+                    while '\\n' in pending:\n+                        line,pending=pending.split('\\n',1)\n+                        if 'perf frames=' in line:\n+                            latest=line.strip()\n+                            if first is None:first=time.monotonic();event('media_started',mode=mode)\n+                        if '视频超过' in line or '视频播放失败' in line:raise RuntimeError(line)\n+                elapsed=time.monotonic()-start\n+                if first is not None and time.monotonic()-first>=60:break\n+                if first is not None and not free_done and time.monotonic()-first>=25:\n+                    c.command('free');free_done=True\n+                if time.monotonic()-last_report>20:\n+                    event('progress',mode=mode,elapsed_s=round(elapsed,1),latest=latest)\n+                    last_report=time.monotonic()\n+            assert first is not None,'No media packets in observation window'\n+            stop=time.monotonic();c.command('desktop ui bilibili-stop')\n+            time.sleep(3);cpu=c.command('desktop cpu-status')\n+            assert 'workers=0' in cpu,'Video worker did not stop'\n+            after=c.command('free');c.command('desktop ui home')\n+            event('stopped',mode=mode,stop_check_elapsed_s=round(time.monotonic()-stop,3),workers_zero=True)\n+        finally:c.close()\n+\n+for mode in [0,1,2]:run_mode(mode)\n+\n+# Cancel after first received packets, while the common three-second gate is shut.\n+with (out/'cancel-preroll.log').open('w',encoding='utf-8') as log:\n+    c=Console(log=log)\n+    try:\n+        c.command('desktop live-test 2');event('preroll_cancel_start')\n+        c.command('desktop ui bilibili-play:6')\n+        start=time.monotonic();pending='';found=False\n+        while time.monotonic()-start<100:\n+            data=c.serial.read(c.serial.in_waiting or 1).decode(errors='replace');log.write(data);log.flush();pending+=data\n+            assert not fault.search(data)\n+            if 'perf frames=0 ' in pending:found=True;break\n+        assert found,'No prebuffer packets observed'\n+        c.command('desktop ui bilibili-stop');time.sleep(3)\n+        cpu=c.command('desktop cpu-status');assert 'workers=0' in cpu\n+        c.command('free');c.command('desktop ui home')\n+        event('preroll_cancel_passed',workers_zero=True)\n+    finally:c.close()\n+event('complete')\n*** End Patch"));
